const ho = 'https://m.qidian.com'


function generateCsrfToken() {
 let jsmy = String(this.cookie.getCookie(ho).match(/_csrfToken=([^;]*)/)?.[1] || '');
return jsmy;
}

function qdtoken() {
let qdtoken = String(this.cookie.getCookie(ho));
return qdtoken;
}

function Map(e) {
  var java = this.java;
  var source = this.source;
  var cookie = this.cookie;
  var cache = this.cache;
  var infomap = source.getLoginInfoMap();
  var map = (infomap !== null && infomap.get(e) && String(infomap.get(e)).length > 0) ? infomap.get(e) : '';
  return String(map);
}

